import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.B8TleWq7.js";const u=JSON.parse('{"title":"What gets created","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/what-gets-created.md","filePath":"getting-started/what-gets-created.md"}'),o={name:"getting-started/what-gets-created.md"};function l(r,e,d,i,c,p){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="what-gets-created" tabindex="-1">What gets created <a class="header-anchor" href="#what-gets-created" aria-label="Permalink to &quot;What gets created&quot;">​</a></h1><p><code>keel.js new</code> copies two kinds of files, listed in <code>keel.manifest.json</code> in the Keel repo.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Meaning</th><th>Changes on <code>update</code>?</th></tr></thead><tbody><tr><td><strong>Owned by Keel</strong></td><td>The framework, its notes, the tooling.</td><td><strong>Replaced.</strong> Never edit these in a game.</td></tr><tr><td><strong>Starter</strong></td><td>The game&#39;s own entry points and settings.</td><td>Copied once by <code>new</code>, then yours. <code>update</code> never touches them.</td></tr></tbody></table><h2 id="the-folder-layout" tabindex="-1">The folder layout <a class="header-anchor" href="#the-folder-layout" aria-label="Permalink to &quot;The folder layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MyGame/</span></span>
<span class="line"><span>  keel.json                          version, commit and hashes of the owned files</span></span>
<span class="line"><span>  CLAUDE.md                          starter: working rules for AI assistants</span></span>
<span class="line"><span>  stylua.toml  selene.toml           owned: formatter and linter settings</span></span>
<span class="line"><span>  .gitignore  .gitattributes  .styluaignore   starter</span></span>
<span class="line"><span>  .vscode/settings.json              starter</span></span>
<span class="line"><span>  .claude/                           hooks and skills (owned), settings.json (starter)</span></span>
<span class="line"><span>  tools/                             keel.js, sourcemap.js, KeelSetup.lua (owned)</span></span>
<span class="line"><span>  Docs/</span></span>
<span class="line"><span>    Start Here.md  Status.md         starter: your notes hub</span></span>
<span class="line"><span>    Systems/Keel/                    owned: Keel&#39;s own notes</span></span>
<span class="line"><span>  src/</span></span>
<span class="line"><span>    ReplicatedStorage/</span></span>
<span class="line"><span>      Keel/                          owned: the framework, shared by server and client</span></span>
<span class="line"><span>      Shared/                        starter: this game&#39;s shared code</span></span>
<span class="line"><span>        Defs/  (Rules, Products, Passes, Subscriptions)</span></span>
<span class="line"><span>        Net.luau                     the list of every network message</span></span>
<span class="line"><span>    ServerScriptService/</span></span>
<span class="line"><span>      KeelServer/                    owned: the framework&#39;s server-only parts and its tests</span></span>
<span class="line"><span>      Server/                        starter: this game&#39;s server code</span></span>
<span class="line"><span>        Main.server.luau             the only server Script</span></span>
<span class="line"><span>        Components/  Services/  Systems/  Tests/</span></span>
<span class="line"><span>        Defs/  (Admins, LiveKeys)</span></span>
<span class="line"><span>        Migrations.luau</span></span>
<span class="line"><span>    ReplicatedFirst/</span></span>
<span class="line"><span>      Client/                        starter: all of this game&#39;s client code</span></span>
<span class="line"><span>        Main.luau  Loading.local.luau  LoadingScreen.luau</span></span>
<span class="line"><span>        Controllers/  Components/  UI/Views/  UI/Widgets/</span></span>
<span class="line"><span>    StarterPlayer/StarterPlayerScripts/</span></span>
<span class="line"><span>      Boot/Boot.local.luau           the tiny client entry point</span></span></code></pre></div><h2 id="owned-by-keel" tabindex="-1">Owned by Keel <a class="header-anchor" href="#owned-by-keel" aria-label="Permalink to &quot;Owned by Keel&quot;">​</a></h2><p>Replaced on every update. A game never edits them.</p><ul><li><code>src/ReplicatedStorage/Keel/</code>: Signal, Trove, Log, Loader, Scheduler, Net, Defs, Entity, State, the client layer, and the vendored Packet and Trove.</li><li><code>src/ServerScriptService/KeelServer/</code>: Data, Replica, Policy, Purchases, LiveDefs, Console (with vendored Cmdr and ProfileStore), and the unit tests.</li><li><code>Docs/Systems/Keel/</code>: Keel&#39;s own notes.</li><li><code>tools/keel.js</code>, <code>tools/sourcemap.js</code>.</li><li><code>tools/KeelSetup.lua</code>: the Studio plugin that creates the Folders and attributes. Copy it into Studio&#39;s Plugins folder once; see <a href="/Keel-Docs/getting-started/connect-studio">Connect Roblox Studio</a>.</li><li>The three hooks in <code>.claude/hooks/</code> (<code>luau-check.js</code>, <code>note-lookup.js</code>, <code>keel-guard.js</code>) and the <code>luau-layout</code> and <code>verify</code> skills.</li><li><code>stylua.toml</code>, <code>selene.toml</code>.</li></ul><h2 id="starter-files" tabindex="-1">Starter files <a class="header-anchor" href="#starter-files" aria-label="Permalink to &quot;Starter files&quot;">​</a></h2><p>Copied once, then the game&#39;s own.</p><ul><li><code>src/ReplicatedStorage/Shared/</code>, <code>src/ServerScriptService/Server/</code>, <code>src/ReplicatedFirst/</code>, <code>src/StarterPlayer/</code></li><li><code>.claude/settings.json</code>, <code>.vscode/settings.json</code>, <code>.styluaignore</code>, <code>.gitignore</code>, <code>.gitattributes</code></li><li><code>CLAUDE.md</code>, <code>Docs/Start Here.md</code>, <code>Docs/Status.md</code></li></ul><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Folders that hold only a <code>.gitkeep</code> (such as <code>Server/Services/</code>) exist on disk so Git keeps them, but Script Sync ignores non-script files, so they do not appear in Studio until you add the first <code>.luau</code> file. That is expected, not a sync problem.</p></div><h2 id="where-each-side-starts" tabindex="-1">Where each side starts <a class="header-anchor" href="#where-each-side-starts" aria-label="Permalink to &quot;Where each side starts&quot;">​</a></h2><ul><li><strong>Server:</strong> <code>Server/Main.server.luau</code>, the only server Script. See <a href="/Keel-Docs/guides/boot-and-folders#boot">Folders and boot</a>.</li><li><strong>Client:</strong> <code>Boot/Boot.local.luau</code>, which loads <code>ReplicatedFirst/Client/Main.luau</code>.</li></ul>`,14)])])}const g=s(o,[["render",l]]);export{u as __pageData,g as default};
